class ArgumentParser:
    """
    This is a class for parsing command line arguments to a dictionary.
    """

    def __init__(self):
        """
        Initialize the fields.
        self.arguments is a dict that stores the args in a command line
        self.required is a set that stores the required arguments
        self.types is a dict that stores type of every arguments.
        >>> parser.arguments
        {'key1': 'value1', 'option1': True}
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'type1'}
        """
        self.arguments = {}
        self.required = set()
        self.types = {}

    def parse_arguments(self, command_string):
        """
        Parses the given command line argument string and invoke _convert_type to stores the parsed result in specific type in the arguments dictionary.
        Checks for missing required arguments, if any, and returns False with the missing argument names, otherwise returns True.
        :param command_string: str, command line argument string, formatted like "python script.py --arg1=value1 -arg2 value2 --option1 -option2"
        :return tuple: (True, None) if parsing is successful, (False, missing_args) if parsing fails,
            where missing_args is a set of the missing argument names which are str.
        >>> parser.parse_arguments("python script.py --arg1=value1 -arg2 value2 --option1 -option2")
        (True, None)
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        """
        # Split the command string into tokens
        tokens = command_string.split()

        # Skip the first two tokens (python script.py)
        tokens = tokens[2:] if len(tokens) > 2 else []

        i = 0
        while i < len(tokens):
            token = tokens[i]

            # Handle --arg=value format
            if token.startswith('--') and '=' in token:
                arg_name = token[2:].split('=')[0]
                arg_value = token[2:].split('=')[1]
                self.arguments[arg_name] = self._convert_type(arg_name, arg_value)
                i += 1
            # Handle --arg or -arg format (flags or arguments with value following)
            elif token.startswith('--') or token.startswith('-'):
                arg_name = token[2:] if token.startswith('--') else token[1:]

                # Check if next token is a value (not a flag)
                if i + 1 < len(tokens) and not tokens[i + 1].startswith('-'):
                    self.arguments[arg_name] = self._convert_type(arg_name, tokens[i + 1])
                    i += 2
                else:
                    # This is a flag (boolean option)
                    self.arguments[arg_name] = True
                    i += 1
            else:
                i += 1

        # Check for missing required arguments
        missing_args = self.required - set(self.arguments.keys())
        if missing_args:
            return (False, missing_args)

        return (True, None)

    def get_argument(self, key):
        """
        Retrieves the value of the specified argument from the arguments dictionary and returns it.
        :param key: str, argument name
        :return: The value of the argument, or None if the argument does not exist.
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        >>> parser.get_argument('arg2')
        'value2'
        """
        return self.arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        """
        Adds an argument to self.types and self.required.
        Check if it is a required argument and store the argument type.
        If the argument is set as required, it wull be added to the required set.
        The argument type and name are stored in the types dictionary as key-value pairs.
        :param arg: str, argument name
        :param required: bool, whether the argument is required, default is False
        :param arg_type:str, Argument type, default is str
        >>> parser.add_argument('arg1', True, 'int')
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'int'}
        """
        self.types[arg] = arg_type
        if required:
            self.required.add(arg)

    def _convert_type(self, arg, value):
        """
        Try to convert the type of input value by searching in self.types.
        :param value: str, the input value in command line
        :return: return corresponding value in self.types if convert successfully, or the input value oherwise
        >>> parser.types
        {'arg1': int}
        >>> parser._convert_type('arg1', '21')
        21
        """
        if arg not in self.types:
            return value

        arg_type = self.types[arg]

        try:
            if arg_type == int:
                return int(value)
            elif arg_type == float:
                return float(value)
            elif arg_type == bool:
                return value.lower() in ('true', '1', 'yes', 'on')
            elif arg_type == str:
                return value
            else:
                # For any other type, try to call the type constructor
                return arg_type(value)
        except (ValueError, TypeError):
            return value

class Interpolation:
    """
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    """

    def __init__(self):
        pass

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]
        """
        def linear_interpolate(x0, x1, y0, y1, x):
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)

        result = []
        for xi in x_interp:
            if xi <= x[0]:
                result.append(y[0])
            elif xi >= x[-1]:
                result.append(y[-1])
            else:
                # Find the interval where xi lies
                for i in range(len(x) - 1):
                    if x[i] <= xi <= x[i+1]:
                        yi = linear_interpolate(x[i], x[i+1], y[i], y[i+1], xi)
                        result.append(yi)
                        break
        return result

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param z: The z-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :param y_interp: The y-coordinate of the interpolation point, list.
        :return: The z-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_2d([1, 2, 3], [1, 2, 3], [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1.5, 2.5], [1.5, 2.5])
        [3.0, 7.0]
        """
        def bilinear_interpolate(x0, x1, y0, y1, f00, f10, f01, f11, x, y):
            return (f00 * (x1 - x) * (y1 - y) +
                    f10 * (x - x0) * (y1 - y) +
                    f01 * (x1 - x) * (y - y0) +
                    f11 * (x - x0) * (y - y0)) / ((x1 - x0) * (y1 - y0))

        result = []
        for xi, yi in zip(x_interp, y_interp):
            if xi <= x[0]:
                xi_adj = x[0]
            elif xi >= x[-1]:
                xi_adj = x[-1]
            else:
                xi_adj = xi

            if yi <= y[0]:
                yi_adj = y[0]
            elif yi >= y[-1]:
                yi_adj = y[-1]
            else:
                yi_adj = yi

            # Find the square where (xi, yi) lies
            x_idx = y_idx = 0
            for i in range(len(x) - 1):
                if x[i] <= xi_adj <= x[i+1]:
                    x_idx = i
                    break
            for i in range(len(y) - 1):
                if y[i] <= yi_adj <= y[i+1]:
                    y_idx = i
                    break

            x0, x1 = x[x_idx], x[x_idx + 1]
            y0, y1 = y[y_idx], y[y_idx + 1]

            f00 = z[y_idx][x_idx]
            f10 = z[y_idx][x_idx + 1]
            f01 = z[y_idx + 1][x_idx]
            f11 = z[y_idx + 1][x_idx + 1]

            z_interp = bilinear_interpolate(x0, x1, y0, y1, f00, f10, f01, f11, xi_adj, yi_adj)
            result.append(z_interp)

        return result

class IPAddress:
    """
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    """

    def __init__(self, ip_address):
        """
        Initialize the IP address to the specified address
        :param ip_address:string
        """
        self.ip_address = ip_address

    def is_valid(self):
        """
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        True
        """
        try:
            octets = self.ip_address.split('.')
            if len(octets) != 4:
                return False

            for octet in octets:
                if not octet.isdigit():
                    return False
                num = int(octet)
                if num < 0 or num > 255:
                    return False
                # Check for leading zeros (except for "0" itself)
                if len(octet) > 1 and octet[0] == '0':
                    return False

            return True
        except:
            return False

    def get_octets(self):
        """
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: list
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        """
        if self.is_valid():
            return self.ip_address.split('.')
        else:
            return []

    def get_binary(self):
        """
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: string
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        """
        if self.is_valid():
            octets = self.ip_address.split('.')
            binary_octets = []
            for octet in octets:
                num = int(octet)
                binary_octets.append(format(num, '08b'))
            return '.'.join(binary_octets)
        else:
            return ''

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """


    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]


    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not self.is_valid_input(textnum):
            raise ValueError("Invalid input string")

        textnum = textnum.replace('-', ' ')
        textnum = textnum.lower().strip()

        # Split into words
        current = result = 0
        for word in textnum.split():
            if word in self.ordinal_words:
                # Handle ordinal words (first, second, etc.)
                result += current
                current = self.ordinal_words[word]
            elif word in self.numwords:
                scale, increment = self.numwords[word]
                current = current * scale + increment
                if scale > 100:
                    result += current
                    current = 0
            else:
                # Try to handle ordinal forms (twenty-first, etc.)
                found = False
                for ending, replacement in self.ordinal_endings:
                    if word.endswith(ending):
                        # Convert ordinal form to cardinal
                        cardinal = word[:-len(ending)] + replacement
                        if cardinal in self.numwords:
                            current += self.numwords[cardinal][1]
                            found = True
                            break
                if not found:
                    raise ValueError(f"Unrecognized word: {word}")

        result += current

        return str(result)


    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if not textnum or not isinstance(textnum, str):
            return False

        textnum = textnum.replace('-', ' ')
        textnum = textnum.lower().strip()
        words = textnum.split()

        if not words:
            return False

        for word in words:
            # Check if word is directly in our dictionary
            if word in self.numwords or word in self.ordinal_words:
                continue

            # Check for ordinal forms
            is_ordinal = False
            for ending, _ in self.ordinal_endings:
                if word.endswith(ending):
                    # Extract cardinal form
                    base_length = len(ending)
                    if base_length <= len(word):
                        cardinal = word[:-base_length]
                        if ending == 'ieth':
                            cardinal = cardinal + 'y'
                        if cardinal in self.numwords and self.numwords[cardinal][1] != 0:
                            is_ordinal = True
                            break
            if not is_ordinal:
                return False

        return True
